'use strict';
(()=>{
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const W=1600,H=1000,TAU=Math.PI*2;
const ui={food:document.getElementById('food'),wood:document.getElementById('wood'),gold:document.getElementById('gold'),stone:document.getElementById('stone'),pop:document.getElementById('pop'),popFill:document.getElementById('popFill'),selection:document.getElementById('selection'),commands:document.getElementById('commands'),hint:document.getElementById('hint'),log:document.getElementById('log'),day:document.getElementById('day'),clock:document.getElementById('clock'),status:document.getElementById('statusText'),toast:document.getElementById('toast')};
let res={food:200,wood:150,gold:100,stone:80},units=[],buildings=[],nodes=[],effects=[],selected=[],mode=null,paused=false,elapsed=0,enemyTimer=36,toastTimer=0,uiTimer=0,gameOver=false,sound=true;
let cam={x:390,y:500,z:1},view={w:800,h:600};
const rand=s=>{let x=Math.sin(s*127.1+311.7)*43758.5453;return x-Math.floor(x)};
function node(type,x,y,amount=800){nodes.push({type,x,y,amount,max:amount,r:type==='tree'?18:type==='gold'?23:type==='stone'?21:15});}
for(let i=0;i<78;i++){let x=35+rand(i+11)*1530,y=28+rand(i+139)*944;if(Math.abs(x-390)<155&&Math.abs(y-500)<145||Math.abs(x-1280)<120&&Math.abs(y-500)<120)continue;let type=x>750&&rand(i+44)<.19?'gold':rand(i+33)<.82?'tree':'stone';node(type,x,y,type==='tree'?480:750)}
for(let i=0;i<5;i++)node('berry',300+(i%3)*27,385+Math.floor(i/3)*28,240);
const makeUnit=(type,x,y,team='blue')=>{let hp=type==='villager'?40:type==='archer'?35:65;let u={type,x,y,team,hp,maxhp:hp,speed:type==='villager'?48:type==='archer'?40:34,selected:false,task:null,target:null,carry:0,attackCd:0,anim:rand(units.length+1)*7,heading:0};units.push(u);return u};
function building(type,x,y,team='blue'){let info={towncenter:[76,72,1000],house:[45,40,300],farm:[48,38,220],tower:[42,48,350],enemy:[76,72,1100]};let [w,h,hp]=info[type];let b={type,x,y,w,h,hp,maxhp:hp,team,attackCd:0};buildings.push(b);return b}
building('towncenter',385,510);building('enemy',1280,500,'red');
for(let i=0;i<4;i++)makeUnit('villager',340+i*30,555+(i%2)*18);
for(let i=0;i<4;i++)makeUnit(i===0?'archer':'soldier',1220+i*25,570+(i%2)*20,'red');
const colors={blue:'#7b9bca',red:'#c27462'};
function log(text,icon='✦'){let d=document.createElement('div');d.className='event-item';d.innerHTML=`<time>${clockText()}</time><span class="event-icon">${icon}</span><span>${text}</span>`;ui.log.prepend(d);while(ui.log.children.length>4)ui.log.lastChild.remove()}
function clockText(){let n=Math.floor(elapsed);return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}
function say(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=2.2}
function canPay(cost){return Object.entries(cost).every(([k,v])=>res[k]>=v)}
function pay(cost){if(!canPay(cost))return false;for(let k in cost)res[k]-=cost[k];return true}
function cap(){return 15+buildings.filter(b=>b.team==='blue'&&b.type==='house').length*5}
function aliveCount(team){return units.filter(u=>u.team===team).length}
function unitLabel(u){return u.type==='villager'?'Villager':u.type==='archer'?'Archer':'Man-at-arms'}
function updateUI(){for(let k in res)ui[k].textContent=Math.floor(res[k]);let n=aliveCount('blue'),c=cap();ui.pop.innerHTML=`${n} <i>/ ${c}</i>`;ui.popFill.style.width=`${Math.min(100,n/c*100)}%`;if(!selected.length){ui.selection.innerHTML='<div class="empty-select"><span class="select-cross">⌖</span><div><b>No unit selected</b><small>Click a villager or soldier</small></div></div>';drawCommands();return}let u=selected[0],label=selected.length>1?`${selected.length} units selected`:unitLabel(u);ui.selection.innerHTML=`<div class="unit-info"><span class="unit-emblem">${u.type==='villager'?'♟':u.type==='archer'?'➶':'⚔'}</span><div><b>${label}</b><small>${u.team==='blue'?(u.task==='gather'?'Gathering resources':u.task==='attack'?'Engaging enemy':u.task==='move'?'Moving':'Ready for orders'):'Enemy'}</small><div class="health-track"><span style="width:${Math.max(0,u.hp/u.maxhp*100)}%"></span></div></div></div>`;drawCommands()}
function commandButton(icon,name,cost,fn,disabled=false){let costText=cost?Object.entries(cost).map(([k,v])=>`${k[0].toUpperCase()}${v}`).join(' '):'';let b=document.createElement('button');b.className='command-btn';b.disabled=disabled;b.innerHTML=`<span class="cost">${costText}</span><span class="cmd-icon">${icon}</span><span class="cmd-name">${name}</span>`;b.onclick=fn;ui.commands.appendChild(b)}
function drawCommands(){ui.commands.innerHTML='';let u=selected[0];if(!u){ui.hint.textContent='Select a unit to see available commands.';return}if(u.team!=='blue'){ui.hint.textContent='Enemy forces cannot be commanded.';return}if(u.type==='villager'){commandButton('⌂','Build house',{wood:60},()=>setMode('house'),!canPay({wood:60}));commandButton('♧','Plant farm',{wood:50},()=>setMode('farm'),!canPay({wood:50}));commandButton('▤','Build tower',{wood:80,stone:50},()=>setMode('tower'),!canPay({wood:80,stone:50}));commandButton('⚒','Gather',null,()=>{ui.hint.textContent='Right-click trees, berries, gold or stone.'});ui.hint.textContent='Build, or right-click a resource to gather.'}else{commandButton('⚔','Attack',null,()=>{ui.hint.textContent='Right-click an enemy to engage.'});commandButton('⌖','Move',null,()=>{mode='move';say('Choose a destination on the map.')});ui.hint.textContent='Right-click to move or attack enemies.'}let tc=buildings.find(b=>b.type==='towncenter'&&b.team==='blue');if(tc&&distance(u,tc)<125)commandButton('♟','Train villager',{food:50},()=>trainVillager(),!canPay({food:50})||aliveCount('blue')>=cap());}
function setMode(type){if(!canPay(type==='house'?{wood:60}:type==='farm'?{wood:50}:{wood:80,stone:50})){say('Not enough resources.');return}mode=type;ui.hint.textContent=`Click a clear spot to place your ${type}. Press Escape to cancel.`;say(`Choose a spot for your ${type}.`)}
function trainVillager(){if(!pay({food:50})){say('Not enough food.');return}if(aliveCount('blue')>=cap()){say('Build a house to increase population.');return}let t=buildings.find(b=>b.type==='towncenter'&&b.team==='blue');makeUnit('villager',t.x+45,t.y+45);log('A villager has joined your settlement.','♟');updateUI()}
function distance(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}

