function distance(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}
function targetAt(pos){let e=units.filter(u=>u.team==='red'&&u.hp>0).concat(buildings.filter(b=>b.team==='red'&&b.hp>0)).sort((a,b)=>distance(pos,a)-distance(pos,b));return e[0]&&distance(pos,e[0])<70?e[0]:null}
function issue(pos){if(!selected.length)return;let enemy=targetAt(pos);if(enemy){selected.forEach(u=>{if(u.team==='blue'&&u.type!=='villager'){u.task='attack';u.target=enemy}});ui.status.textContent='Your soldiers are engaging the enemy.';return}let r=nodes.filter(n=>n.amount>0&&distance(n,pos)<n.r+14).sort((a,b)=>distance(a,pos)-distance(b,pos))[0];if(r&&selected.some(u=>u.type==='villager')){selected.filter(u=>u.type==='villager').forEach(u=>{u.task='gather';u.target=r});ui.status.textContent=`Villagers gathering ${r.type}.`;return}selected.forEach(u=>{u.task='move';u.target={x:pos.x,y:pos.y}});ui.status.textContent='Units moving to the selected position.';mode=null}
function placeBuilding(pos){let type=mode,cost=type==='house'?{wood:60}:type==='farm'?{wood:50}:{wood:80,stone:50};if(!canPay(cost)){say('Not enough resources.');mode=null;return}if(pos.x<50||pos.x>W-50||pos.y<50||pos.y>H-50||buildings.some(b=>Math.abs(pos.x-b.x)<b.w*.7+40&&Math.abs(pos.y-b.y)<b.h*.7+35)||nodes.some(n=>n.type==='tree'&&distance(n,pos)<n.r+22)){say('That spot is blocked.');return}pay(cost);let b=building(type,pos.x,pos.y);if(type==='farm')node('farm',pos.x,pos.y,550);log(`${type[0].toUpperCase()+type.slice(1)} completed.`,'⌂');say(`${type[0].toUpperCase()+type.slice(1)} placed.`);mode=null;updateUI()}
function moveToward(a,b,dt,speed=a.speed||35){let d=distance(a,b);if(d<2)return true;let step=Math.min(d,speed*dt),dx=(b.x-a.x)/d,dy=(b.y-a.y)/d;a.x+=dx*step;a.y+=dy*step;a.heading=Math.atan2(dy,dx);return d<step+3}
function update(dt){if(paused||gameOver)return;elapsed+=dt;enemyTimer-=dt;for(let u of units){if(u.hp<=0)continue;u.anim+=dt*6;if(u.team==='blue'&&u.task==='gather'&&u.target){let n=u.target;if(n.amount<=0){u.target=null;u.task=null;continue}if(u.carry>=20){let home=buildings.find(b=>b.team==='blue'&&b.type==='towncenter');if(home&&distance(u,home)>70){moveToward(u,{x:home.x,y:home.y},dt);continue}if(home){res[n.type==='berry'||n.type==='farm'?'food':n.type==='tree'?'wood':n.type]+=u.carry;u.carry=0}continue}if(distance(u,n)>n.r+7)moveToward(u,n,dt);else{let amt=Math.min(8*dt,n.amount,20-u.carry);n.amount-=amt;u.carry+=amt}}else if(u.task==='move'&&u.target){if(moveToward(u,u.target,dt)){u.task=null;u.target=null}}else if(u.task==='attack'&&u.target&&u.target.hp>0){let t=u.target,range=t.w?68:u.type==='archer'?115:22;if(distance(u,t)>range){moveToward(u,t,dt)}else{u.attackCd-=dt;if(u.attackCd<=0){t.hp-=u.type==='archer'?9:13;u.attackCd=u.type==='archer'?1.1:0.85;effects.push({x:t.x,y:t.y,life:.22,color:'#ffdb87'});if(t.hp<=0)killed(t)}}}else if(u.team==='red'){let home=buildings.find(b=>b.team==='blue'&&b.type==='towncenter');if(home&&distance(u,home)>55)moveToward(u,home,dt);else if(home){u.attackCd-=dt;if(u.attackCd<=0){home.hp-=5;u.attackCd=1.2;if(home.hp<=0)endGame(false)}}}}
for(let b of buildings){if(b.type==='tower'&&b.team==='blue'){b.attackCd-=dt;if(b.attackCd<=0){let e=units.find(u=>u.team==='red'&&u.hp>0&&distance(u,b)<190);if(e){e.hp-=15;b.attackCd=1.4;effects.push({x:e.x,y:e.y,life:.25,color:'#ffd36d'});if(e.hp<=0)killed(e)}}}}
if(enemyTimer<=0){enemyTimer=Math.max(24,56-elapsed*.12);let home=buildings.find(b=>b.team==='blue'&&b.type==='towncenter');if(home&&Math.random()<.78){let count=elapsed>180?3:2;for(let i=0;i<count;i++)makeUnit(Math.random()<.3?'archer':'soldier',1270+Math.random()*65,535+Math.random()*70,'red');log('Scouts report an enemy war party approaching.','⚠');say('Enemy raiders are gathering!')}}
for(let i=units.length-1;i>=0;i--)if(units[i].hp<=0){if(units[i].team==='blue')log(`${unitLabel(units[i])} lost in battle.`,'⚔');units.splice(i,1)}
for(let i=effects.length-1;i>=0;i--){effects[i].life-=dt;if(effects[i].life<=0)effects.splice(i,1)}if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show')}uiTimer-=dt;if(uiTimer<=0){updateUI();ui.clock.textContent=clockText();ui.day.textContent=String(1+Math.floor(elapsed/120)).padStart(2,'0');uiTimer=.3}if(buildings.find(b=>b.team==='red'&&b.type==='enemy'&&b.hp<=0))endGame(true)}
function killed(t){effects.push({x:t.x,y:t.y,life:.5,color:'#ffbf63'});if(t.team==='red')log('An enemy has fallen.','⚔')}
function endGame(win){if(gameOver)return;gameOver=true;paused=true;say(win?'Victory! The rival stronghold has fallen.':'Defeat. Your Town Center has fallen.');log(win?'The Greenmere valley is yours!':'The settlement has been overrun.',win?'✦':'⚠');setTimeout(()=>{let cover=document.createElement('div');cover.className='modal-backdrop open';cover.innerHTML=`<div class="modal"><div class="section-label"><span class="gold-line"></span> CAMPAIGN COMPLETE</div><h2>${win?'Victory at Greenmere':'The valley is lost'}</h2><p class="modal-intro">${win?'Your forces have brought the rival stronghold to its knees. Greenmere belongs to your people.':'The rival clan overwhelmed your settlement. Regroup and try a new strategy.'}</p><button class="primary-btn" onclick="location.reload()">${win?'PLAY AGAIN':'TRY AGAIN'} <span>→</span></button></div>`;document.body.appendChild(cover)},400)}

