let dpr=1;function resize(){let r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr);view.w=r.width;view.h=r.height}
function render(){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,view.w,view.h);ctx.setTransform(dpr*cam.z,0,0,dpr*cam.z,dpr*(view.w/2-cam.x*cam.z),dpr*(view.h/2-cam.y*cam.z));drawGround();for(let n of nodes)drawNode(n);for(let b of buildings)drawBuilding(b);let all=units.filter(u=>u.hp>0).slice().sort((a,b)=>a.y-b.y);for(let u of all)drawUnit(u);for(let e of effects){ctx.globalAlpha=Math.max(0,e.life*4);ctx.fillStyle=e.color;ctx.beginPath();ctx.arc(e.x,e.y,13+(1-e.life)*16,0,TAU);ctx.fill();ctx.globalAlpha=1}if(pointer&&pointer.dragging&&pointer.box){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.strokeStyle='#e7d09a';ctx.fillStyle='#dbc89122';ctx.lineWidth=1;let x=Math.min(pointer.x,pointer.cx),y=Math.min(pointer.y,pointer.cy),w=Math.abs(pointer.x-pointer.cx),h=Math.abs(pointer.y-pointer.cy);ctx.fillRect(x,y,w,h);ctx.strokeRect(x,y,w,h)}}
let pointer=null,keys={};function screenPos(e){let r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}}
function hitUnit(p){let w=world(p.x,p.y);return units.filter(u=>u.team==='blue'&&u.hp>0&&distance(u,w)<15/cam.z).sort((a,b)=>distance(a,w)-distance(b,w))[0]}
canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('pointerdown',e=>{canvas.setPointerCapture(e.pointerId);let p=screenPos(e),u=hitUnit(p);if(e.button===1||keys.Space){pointer={...p,cx:p.x,cy:p.y,dragging:true,pan:true,wx:cam.x,wy:cam.y};return}if(e.button===2){issue(world(p.x,p.y));return}if(mode){placeBuilding(world(p.x,p.y));return}if(u){if(!e.shiftKey)selected.forEach(v=>v.selected=false);if(!selected.includes(u))selected.push(u);u.selected=true;updateUI();pointer={...p,cx:p.x,cy:p.y,dragging:false,box:true};return}if(e.pointerType==='touch'&&selected.length){issue(world(p.x,p.y));return}pointer={...p,cx:p.x,cy:p.y,dragging:false,box:selected.length>0,pan:!selected.length,wx:cam.x,wy:cam.y}});
canvas.addEventListener('pointermove',e=>{if(!pointer)return;let p=screenPos(e);pointer.x=p.x;pointer.y=p.y;if(Math.hypot(p.x-pointer.cx,p.y-pointer.cy)>5)pointer.dragging=true;if(pointer.dragging&&pointer.pan){cam.x=pointer.wx-(p.x-pointer.cx)/cam.z;cam.y=pointer.wy-(p.y-pointer.cy)/cam.z} });
canvas.addEventListener('pointerup',e=>{if(!pointer)return;let p=screenPos(e);if(pointer.dragging&&pointer.box){let a=world(Math.min(pointer.cx,p.x),Math.min(pointer.cy,p.y)),b=world(Math.max(pointer.cx,p.x),Math.max(pointer.cy,p.y));if(!e.shiftKey)selected.forEach(u=>u.selected=false),selected=[];units.filter(u=>u.team==='blue'&&u.hp>0&&u.x>=a.x&&u.x<=b.x&&u.y>=a.y&&u.y<=b.y).forEach(u=>{if(!selected.includes(u)){u.selected=true;selected.push(u)}});updateUI()}else if(!pointer.dragging&&!pointer.pan&&!hitUnit(p)){if(e.pointerType==='touch'&&selected.length)issue(world(p.x,p.y));else if(selected.length){selected.forEach(u=>u.selected=false);selected=[];updateUI()}}pointer=null});
